    /**
 * Links, or with a null id unlinks, the transfer that brought the paid money back to checking. Informational: changes no balance. Only the outgoing leg of a transfer out of the position's own account that no other position claims is accepted, and a linked transfer cannot be deleted.

 */
export const linkPositionReturnTransfer = (
    workspaceId: string,
    positionId: string,
    positionReturnTransferRequest: PositionReturnTransferRequest,
 ) => {
      
      
      return apiFetch<Position>(
      {url: `/workspaces/${workspaceId}/investments/positions/${positionId}/return-transfer`, method: 'PUT',
      headers: {'Content-Type': 'application/json', },
      data: positionReturnTransferRequest
    },
      );
    }
  


